/**
 * In-memory data for mock mode, so the UI agents can build complete flows
 * (add an item, see it in the grid, get outfits, save one) before the real
 * backend exists. The API route stubs serve this data until their owning
 * agents replace them with real implementations.
 *
 * Outfits are generated by the real pipeline in src/lib/outfits/ (with a
 * mock ranking model); this file only stores them. Outfits with gaps
 * (milestone 5) are canned until the engine makes them (mockGapOutfits).
 */
import {
  DEFAULT_FAVOURITE_SHOP_IDS,
  LINK_IMPORT_TTL_SECONDS,
  PLACEHOLDER_ITEM_IMAGE_URL,
  SHOPS_BY_ID,
  SHOP_PRODUCTS_PER_GAP,
  type Category,
  type CreateItemRequest,
  type EmailImport,
  type FeedbackKind,
  type ItemDraft,
  type ItemListQuery,
  type ItemTags,
  type LinkProduct,
  type Outfit,
  type OutfitGap,
  type OutfitStatus,
  type ShopId,
  type ShopProduct,
  type StoredOutfitRequest,
  type WardrobeItem,
} from "@/contracts";
import { MOCK_USER } from "@/lib/auth/session";
import {
  MOCK_EMAIL_LINE_ITEMS,
  MOCK_FORWARDING_TOKEN,
  MOCK_GAP_OUTFITS,
  MOCK_ITEMS,
  MOCK_SUGGESTED_TAGS,
  MOCK_UPLOAD_IMAGE_URL,
} from "./fixtures";

export interface MockLinkImport {
  userId: string;
  sourceUrl: string;
  product: LinkProduct;
  createdAt: number;
  tagged: boolean;
}

interface MockState {
  items: Map<string, WardrobeItem>;
  outfits: Map<string, Outfit>;
  /** Image key -> URL for drafts that haven't been saved yet. */
  draftImages: Map<string, string>;
  /** Add-by-link step 1 results, by original image key (the link_imports table). */
  linkImports: Map<string, MockLinkImport>;
  /** outfit_feedback rows. */
  feedback: MockOutfitFeedback[];
  /** The mock user's user_settings row. */
  settings: { favouriteShopIds: ShopId[]; forwardingToken: string };
  /** email_imports rows, newest first. */
  emailImports: EmailImport[];
}

export interface MockOutfitFeedback {
  outfitId: string;
  kind: FeedbackKind;
  detail: string | null;
  createdAt: string;
}

function freshState(): MockState {
  return {
    items: new Map(MOCK_ITEMS.map((item) => [item.id, structuredClone(item)])),
    outfits: new Map(),
    draftImages: new Map(),
    linkImports: new Map(),
    feedback: [],
    settings: { favouriteShopIds: [...DEFAULT_FAVOURITE_SHOP_IDS], forwardingToken: MOCK_FORWARDING_TOKEN },
    emailImports: [],
  };
}

// On globalThis so data survives dev-server hot reloads.
const globalForMocks = globalThis as unknown as { __gladragsMockState?: MockState };

function state(): MockState {
  globalForMocks.__gladragsMockState ??= freshState();
  return globalForMocks.__gladragsMockState;
}

/** Back to the fixture wardrobe with no outfits. For tests. */
export function resetMockStore(): void {
  globalForMocks.__gladragsMockState = freshState();
}

const now = () => new Date().toISOString();
const clone = <T>(value: T): T => structuredClone(value);

// ---------------------------------------------------------------------------
// Items
// ---------------------------------------------------------------------------

export function listItems(query: ItemListQuery = {}): WardrobeItem[] {
  const q = query.q?.toLowerCase();
  return [...state().items.values()]
    .filter((item) => !query.category || item.tags.category === query.category)
    .filter((item) => !query.colour || item.tags.colours.includes(query.colour))
    .filter((item) => !query.occasion || item.tags.occasions.includes(query.occasion))
    .filter((item) => !q || item.tags.description.toLowerCase().includes(q))
    .filter((item) => query.needsReview === undefined || item.needsReview === query.needsReview)
    .map(clone);
}

export function getItem(id: string): WardrobeItem | null {
  const item = state().items.get(id);
  return item ? clone(item) : null;
}

/** A new image key in the mock user's folder. */
function newImageKey(ext: "jpg" | "png"): string {
  const key = `${MOCK_USER.id}/${crypto.randomUUID()}.${ext}`;
  state().draftImages.set(key, MOCK_UPLOAD_IMAGE_URL);
  return key;
}

/**
 * What the photo route (and link step 2) return in mock mode. Pass the
 * original's key when it was already stored (link step 1).
 */
export function createDraft(options: {
  source: ItemDraft["source"];
  sourceUrl: string | null;
  hasCutout: boolean;
  originalImageKey?: string;
  /** Simulate tagging failing twice (the empty-tags fallback). */
  taggingFails?: boolean;
}): ItemDraft {
  const originalImageKey = options.originalImageKey ?? newImageKey("jpg");
  const cutoutImageKey = options.hasCutout ? newImageKey("png") : null;
  return {
    source: options.source,
    sourceUrl: options.sourceUrl,
    originalImageKey,
    cutoutImageKey,
    originalUrl: MOCK_UPLOAD_IMAGE_URL,
    cutoutUrl: cutoutImageKey ? MOCK_UPLOAD_IMAGE_URL : null,
    suggestedTags: options.taggingFails ? null : clone(MOCK_SUGGESTED_TAGS),
  };
}

/**
 * Link step 1 in mock mode: "store" the product image as the original and
 * remember the import, as the link_imports table does.
 */
export function storeLinkImport(
  userId: string,
  sourceUrl: string,
  product: LinkProduct,
): { originalImageKey: string; originalUrl: string } {
  const originalImageKey = newImageKey("jpg");
  state().linkImports.set(originalImageKey, {
    userId,
    sourceUrl,
    product: clone(product),
    createdAt: Date.now(),
    tagged: false,
  });
  return { originalImageKey, originalUrl: MOCK_UPLOAD_IMAGE_URL };
}

/**
 * Link step 2 in mock mode: claim the import once. Null if it doesn't
 * exist, isn't this user's, has expired, or was already used.
 */
export function claimLinkImport(userId: string, originalImageKey: string): MockLinkImport | null {
  const record = state().linkImports.get(originalImageKey);
  if (!record || record.userId !== userId || record.tagged) return null;
  if (Date.now() - record.createdAt > LINK_IMPORT_TTL_SECONDS * 1000) return null;
  record.tagged = true;
  return clone(record);
}

export function createItem(req: CreateItemRequest): WardrobeItem {
  const s = state();
  const item: WardrobeItem = {
    id: crypto.randomUUID(),
    source: req.source,
    sourceUrl: req.sourceUrl,
    originalUrl: s.draftImages.get(req.originalImageKey) ?? MOCK_UPLOAD_IMAGE_URL,
    cutoutUrl: req.cutoutImageKey ? (s.draftImages.get(req.cutoutImageKey) ?? MOCK_UPLOAD_IMAGE_URL) : null,
    tags: clone(req.tags),
    tagsEdited: req.tagsEdited,
    needsReview: false,
    needsPhoto: false,
    createdAt: now(),
  };
  s.items.set(item.id, item);
  return clone(item);
}

/** PATCH /api/items/[id]: new tags (if sent) and, either way, reviewed. */
export function updateItem(id: string, change: { tags?: ItemTags; reviewed?: true }): WardrobeItem | null {
  const item = state().items.get(id);
  if (!item) return null;
  if (change.tags) {
    item.tags = clone(change.tags);
    item.tagsEdited = true;
  }
  item.needsReview = false;
  return clone(item);
}

export function updateItemTags(id: string, tags: ItemTags): WardrobeItem | null {
  return updateItem(id, { tags });
}

/** POST /api/items/reviewed. Returns how many of the IDs were items. */
export function markItemsReviewed(ids: readonly string[]): number {
  let updated = 0;
  for (const id of ids) {
    const item = state().items.get(id);
    if (!item) continue;
    item.needsReview = false;
    updated++;
  }
  return updated;
}

/**
 * A batch add in mock mode: save the draft straight away as "to review"
 * (needs its suggested tags).
 */
export function saveDraftForReview(draft: ItemDraft & { suggestedTags: ItemTags }): WardrobeItem {
  const item = createItem({
    source: draft.source,
    sourceUrl: draft.sourceUrl,
    originalImageKey: draft.originalImageKey,
    cutoutImageKey: draft.cutoutImageKey,
    tags: draft.suggestedTags,
    tagsEdited: false,
  });
  state().items.get(item.id)!.needsReview = true;
  return { ...item, needsReview: true };
}

/** PUT /api/items/[id]/cutout in mock mode: the uploaded cut-out shows as the mock upload picture. */
export function setItemCutout(id: string): WardrobeItem | null {
  const item = state().items.get(id);
  if (!item) return null;
  item.cutoutUrl = MOCK_UPLOAD_IMAGE_URL;
  return clone(item);
}

/** PUT /api/items/[id]/photo in mock mode. */
export function replaceItemPhoto(id: string): WardrobeItem | null {
  const item = state().items.get(id);
  if (!item) return null;
  item.originalUrl = MOCK_UPLOAD_IMAGE_URL;
  item.cutoutUrl = null;
  item.needsPhoto = false;
  item.needsReview = true;
  return clone(item);
}

/** Also removes outfits that used the item, as the database trigger does. */
export function deleteItem(id: string): boolean {
  const s = state();
  if (!s.items.delete(id)) return false;
  for (const [outfitId, outfit] of s.outfits) {
    if (outfit.itemIds.includes(id)) s.outfits.delete(outfitId);
  }
  return true;
}

// ---------------------------------------------------------------------------
// Outfits
// ---------------------------------------------------------------------------

export function listOutfits(status?: OutfitStatus): Outfit[] {
  return [...state().outfits.values()]
    .filter((o) => !status || o.status === status)
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt))
    .map(clone);
}

export function getOutfit(id: string): Outfit | null {
  const outfit = state().outfits.get(id);
  return outfit ? clone(outfit) : null;
}

export function setOutfitStatus(id: string, status: OutfitStatus): Outfit | null {
  const outfit = state().outfits.get(id);
  if (!outfit) return null;
  outfit.status = status;
  return clone(outfit);
}

/** Save a new outfit (the outfit engine builds it). */
export function insertOutfit(outfit: Outfit): Outfit {
  state().outfits.set(outfit.id, clone(outfit));
  return clone(outfit);
}

/** Feedback rows (the outfit_feedback table): append-only. */
export function addOutfitFeedback(feedback: MockOutfitFeedback): void {
  state().feedback.push(clone(feedback));
}

export function listOutfitFeedback(): MockOutfitFeedback[] {
  return state().feedback.map(clone);
}

/**
 * Canned outfits with gaps (a shoes gap in each), stored like any other,
 * for the UI until the engine makes gaps itself. Built from the fixture
 * wardrobe; an outfit whose items were deleted is skipped.
 */
export function mockGapOutfits(request: StoredOutfitRequest): Outfit[] {
  const createdAt = now();
  const outfits: Outfit[] = [];
  for (const canned of MOCK_GAP_OUTFITS) {
    const items = canned.itemIds.map((id) => state().items.get(id));
    if (items.some((item) => !item)) continue;
    outfits.push(
      insertOutfit({
        id: crypto.randomUUID(),
        request,
        name: canned.name,
        reason: canned.reason,
        itemIds: [...canned.itemIds],
        items: items.map((item) => clone(item!)),
        gaps: canned.gaps.map((gap) => ({ ...clone(gap), shopResults: [], searchedAt: null, shopProduct: null })),
        status: "suggested",
        parentOutfitId: null,
        createdAt,
      }),
    );
  }
  return outfits;
}

function mockProduct(shopId: ShopId, gap: OutfitGap, n: number): ShopProduct {
  const shop = SHOPS_BY_ID[shopId];
  const slug = gap.description.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  return {
    shopId,
    title: `${gap.description} (${shop.name})`,
    url: `https://www.${shop.domains[0]}/mock-product/${slug}-${n}`,
    priceText: `£${25 + n * 10}`,
    imageUrl: n === 2 ? null : MOCK_UPLOAD_IMAGE_URL,
  };
}

/**
 * "Find in my shops" in mock mode: up to three made-up products per gap
 * from the user's favourite shops (the third has no image). Null if the
 * outfit doesn't exist.
 */
export function mockShopSearch(outfitId: string): Outfit | null {
  const outfit = state().outfits.get(outfitId);
  if (!outfit) return null;
  const shops = state().settings.favouriteShopIds;
  const searchedAt = now();
  for (const gap of outfit.gaps) {
    gap.shopResults = Array.from({ length: SHOP_PRODUCTS_PER_GAP }, (_, n) => mockProduct(shops[n % shops.length]!, gap, n));
    gap.searchedAt = searchedAt;
  }
  return clone(outfit);
}

/**
 * Pick (or clear, with null) the product for an outfit's gap. "no_gap"
 * if the outfit has no gap in that category, "not_a_result" if the URL
 * isn't one of its results, null if there's no such outfit.
 */
export function chooseGapProduct(
  outfitId: string,
  category: Category,
  productUrl: string | null,
): Outfit | "no_gap" | "not_a_result" | null {
  const outfit = state().outfits.get(outfitId);
  if (!outfit) return null;
  const gap = outfit.gaps.find((g) => g.category === category);
  if (!gap) return "no_gap";
  if (productUrl === null) {
    gap.shopProduct = null;
  } else {
    const product = gap.shopResults.find((p) => p.url === productUrl);
    if (!product) return "not_a_result";
    gap.shopProduct = clone(product);
  }
  return clone(outfit);
}

// ---------------------------------------------------------------------------
// Settings and order emails
// ---------------------------------------------------------------------------

export function getSettings(): { favouriteShopIds: ShopId[]; forwardingToken: string } {
  return clone(state().settings);
}

export function setFavouriteShops(ids: readonly ShopId[]): void {
  state().settings.favouriteShopIds = [...ids];
}

/** A new random forwarding token; the old address stops working. */
export function resetForwardingToken(): string {
  const token = crypto.randomUUID().replaceAll("-", "");
  state().settings.forwardingToken = token;
  return token;
}

export function listEmailImports(limit: number): EmailImport[] {
  return state().emailImports.slice(0, limit).map(clone);
}

/**
 * An accepted order email in mock mode: adds the fixture line items to the
 * wardrobe as "to review" (the last one without a picture: needsPhoto) and
 * records the import. Doesn't touch the daily caps beyond what the route does.
 */
export function addMockEmailImport(receivedAt: string): EmailImport {
  let itemCount = 0;
  for (const line of MOCK_EMAIL_LINE_ITEMS) {
    const item: WardrobeItem = {
      id: crypto.randomUUID(),
      source: "email",
      sourceUrl: line.productUrl,
      originalUrl: line.hasPicture ? MOCK_UPLOAD_IMAGE_URL : PLACEHOLDER_ITEM_IMAGE_URL,
      cutoutUrl: null,
      tags: clone(line.tags),
      tagsEdited: false,
      needsReview: true,
      needsPhoto: !line.hasPicture,
      createdAt: now(),
    };
    state().items.set(item.id, item);
    itemCount++;
  }
  const record: EmailImport = {
    id: crypto.randomUUID(),
    receivedAt,
    shopName: "M&S",
    orderDate: receivedAt.slice(0, 10),
    status: "done",
    itemCount,
    skippedCount: 0,
    error: null,
  };
  state().emailImports.unshift(record);
  return clone(record);
}

/** A refused or failed email in mock mode: recorded with its reason, nothing added. */
export function addFailedEmailImport(receivedAt: string, error: EmailImport["error"]): EmailImport {
  const record: EmailImport = {
    id: crypto.randomUUID(),
    receivedAt,
    shopName: null,
    orderDate: null,
    status: "failed",
    itemCount: 0,
    skippedCount: 0,
    error,
  };
  state().emailImports.unshift(record);
  return clone(record);
}
